class NoorApp extends StatefulWidget{const NoorApp({super.key});@override State<NoorApp> createState()=>_NoorAppState();}
class _NoorAppState extends State<NoorApp>{bool dark=false;@override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,title:'Noor',themeMode:dark?ThemeMode.dark:ThemeMode.light,theme:ThemeData(useMaterial3:true,colorScheme:ColorScheme.fromSeed(seedColor:olive),scaffoldBackgroundColor:ivory),darkTheme:ThemeData(useMaterial3:true,brightness:Brightness.dark,colorScheme:ColorScheme.fromSeed(seedColor:olive,brightness:Brightness.dark),scaffoldBackgroundColor:deepOlive),home:NoorShell(onTheme:()=>setState(()=>dark=!dark)));}
class NoorShell extends StatefulWidget{final VoidCallback onTheme;const NoorShell({super.key,required this.onTheme});@override State<NoorShell> createState()=>_NoorShellState();}
class _NoorShellState extends State<NoorShell>{int tab=0,tasbeeh=0;@override void initState(){super.initState();_load();}Future<void>_load()async{final p=await SharedPreferences.getInstance();setState(()=>tasbeeh=p.getInt('tasbeeh')??0);}Future<void>_count()async{final p=await SharedPreferences.getInstance();final n=tasbeeh+1;await p.setInt('tasbeeh',n);setState(()=>tasbeeh=n);} @override Widget build(BuildContext c){final pages=[HomePage(tasbeeh:tasbeeh),const QuranPage(),const PrayerPage(),const AzkarPage(),MorePage(tasbeeh:tasbeeh,onCount:_count,onTheme:widget.onTheme)];return Scaffold(body:pages[tab],bottomNavigationBar:NavigationBar(selectedIndex:tab,onDestinationSelected:(i)=>setState(()=>tab=i),destinations:const[NavigationDestination(icon:Icon(Icons.home_outlined),selectedIcon:Icon(Icons.home),label:'الرئيسية'),NavigationDestination(icon:Icon(Icons.menu_book_outlined),selectedIcon:Icon(Icons.menu_book),label:'القرآن'),NavigationDestination(icon:Icon(Icons.access_time),selectedIcon:Icon(Icons.access_time_filled),label:'الصلاة'),NavigationDestination(icon:Icon(Icons.favorite_outline),selectedIcon:Icon(Icons.favorite),label:'الأذكار'),NavigationDestination(icon:Icon(Icons.apps_outlined),selectedIcon:Icon(Icons.apps),label:'المزيد')]),floatingActionButton:tab==4?FloatingActionButton.extended(onPressed:_count,backgroundColor:crimson,icon:const Icon(Icons.radio_button_checked),label:Text('تسبيح $tasbeeh')):null);}}
