class QuranPage extends StatelessWidget{const QuranPage({super.key});final surahs=const['الفاتحة','البقرة','آل عمران','النساء','المائدة','الأنعام','الأعراف','الأنفال','التوبة','يونس','هود','يوسف'];@override Widget build(BuildContext c)=>Column(children:[const NoorHeader(title:'القرآن الكريم',subtitle:'اقرأ بتدبر وطمأنينة'),Padding(padding:const EdgeInsets.all(16),child:TextField(decoration:InputDecoration(prefixIcon:const Icon(Icons.search),hintText:'ابحث في القرآن',filled:true,border:OutlineInputBorder(borderRadius:BorderRadius.all(Radius.circular(18)),borderSide:BorderSide.none)))),Expanded(child:ListView.builder(itemCount:surahs.length,itemBuilder:(_,i)=>ListTile(leading:CircleAvatar(backgroundColor:olive,foregroundColor:Colors.white,child:Text('${i+1}')),title:Text(surahs[i],style:const TextStyle(fontSize:18,fontWeight:FontWeight.w600)),subtitle:Text(i==1?'286 آية':'سورة من القرآن الكريم'),trailing:const Icon(Icons.play_circle_outline,color:crimson),onTap:()=>showModalBottomSheet(context:c,builder:(_)=>SafeArea(child:Column(mainAxisSize:MainAxisSize.min,children:[ListTile(leading:const Icon(Icons.menu_book),title:Text('قراءة ${surahs[i]}')),ListTile(leading:const Icon(Icons.play_circle),title:const Text('تشغيل التلاوة'),onTap:()=>Navigator.pop(c)),ListTile(leading:const Icon(Icons.bookmark_border),title:const Text('حفظ كعلامة'),onTap:()=>Navigator.pop(c))])))))]);}
